args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?film ?filmLabel ?director ?directorLabel ?birthDate WHERE {
  VALUES ?film { dbr:Romance_on_the_Run dbr:The_Palace_of_Angels }
  ?film dbo:director ?director .
  OPTIONAL { ?director dbo:birthDate ?birthDate . }
  OPTIONAL { ?film rdfs:label ?filmLabel . FILTER (lang(?filmLabel) = "en") }
  OPTIONAL { ?director rdfs:label ?directorLabel . FILTER (lang(?directorLabel) = "en") }
}

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?film ?filmLabel ?director ?directorLabel ?birthDate WHERE {
  dbr:Romance_on_the_Run dbo:director ?dir1 .
  dbr:The_Palace_of_Angels dbo:director ?dir2 .
  ?dir1 dbo:birthDate ?birth1 .
  ?dir2 dbo:birthDate ?birth2 .
  {
    FILTER (?birth1 > ?birth2)
    BIND(dbr:Romance_on_the_Run AS ?film)
    BIND(?dir1 AS ?director)
    BIND(?birth1 AS ?birthDate)
  }
  UNION
  {
    FILTER (?birth2 > ?birth1)
    BIND(dbr:The_Palace_of_Angels AS ?film)
    BIND(?dir2 AS ?director)
    BIND(?birth2 AS ?birthDate)
  }
  OPTIONAL { ?film rdfs:label ?filmLabel . FILTER(lang(?filmLabel) = "en") }
  OPTIONAL { ?director rdfs:label ?directorLabel . FILTER(lang(?directorLabel) = "en") }
}

